<?php
require_once __DIR__.'/crm-write.php';
if(!function_exists('g93_create_commission')){function g93_create_commission($exec,$title,$prompt,$priority=250,$metadata=[]){try{return g93_safe_insert('executive_commissions',['commission_uid'=>g93_uid('commission'),'executive_key'=>strtolower($exec),'executive'=>ucfirst($exec),'title'=>$title,'description'=>$prompt,'prompt'=>$prompt,'status'=>'queued','priority'=>$priority,'progress'=>0,'current_step'=>'Queued by Revenue Engine','metadata'=>g93_json($metadata),'created_at'=>gdb_now(),'updated_at'=>gdb_now()]);}catch(Throwable $e){g93_log_failure($metadata['lead_uid']??'',$exec.'_commission',$e->getMessage(),$metadata);return null;}}}
if(!function_exists('g93_create_local_task')){function g93_create_local_task($agent,$commissionId,$taskType,$prompt,$priority=250,$metadata=[]){try{return g93_safe_insert('local_ai_tasks',['task_uid'=>g93_uid('lat'),'commission_id'=>$commissionId,'agent'=>ucfirst($agent),'task_type'=>$taskType,'model'=>'goliath-local-worker','prompt'=>$prompt,'status'=>'queued','priority'=>$priority,'progress'=>0,'metadata'=>g93_json($metadata),'created_at'=>gdb_now(),'updated_at'=>gdb_now()]);}catch(Throwable $e){g93_log_failure($metadata['lead_uid']??'',$agent.'_task',$e->getMessage(),$metadata);return null;}}}
if(!function_exists('g93_callback_time')){function g93_callback_time($lead){$score=(int)($lead['lead_score']??50);if($score>=85)return date('Y-m-d H:i:s',strtotime('+30 minutes'));$hour=(int)date('G');if($hour>=8&&$hour<17)return date('Y-m-d H:i:s',strtotime('+2 hours'));return date('Y-m-d H:i:s',strtotime('tomorrow 9:00'));}}
if(!function_exists('g93_create_callback')){function g93_create_callback($lead,$crmId){$when=g93_callback_time($lead);$id=g93_safe_insert('goliath_callback_tasks',['task_uid'=>g93_uid('callback'),'lead_uid'=>$lead['lead_uid'],'crm_contact_id'=>$crmId,'title'=>'Callback: '.($lead['name']?:$lead['type']),'contact_name'=>$lead['name'],'phone'=>$lead['phone'],'email'=>$lead['email'],'town'=>$lead['town'],'lead_type'=>$lead['type'],'priority'=>max(1,(int)ceil(($lead['lead_score']??50)/20)),'status'=>'queued','scheduled_for'=>$when,'calendar_status'=>'pending','notes'=>'Revenue Engine callback task. Mark should personally call unless later delegated.','metadata'=>g93_json($lead),'created_at'=>gdb_now(),'updated_at'=>gdb_now()]);g93_timeline($lead['lead_uid'],$crmId,'Jessica','callback_queued','Callback task queued','Suggested callback: '.$when,['callback_id'=>$id,'scheduled_for'=>$when]);return $id;}}
if(!function_exists('g93_trigger_executives')){function g93_trigger_executives($lead,$crmId){$meta=['lead_uid'=>$lead['lead_uid'],'crm_contact_id'=>$crmId,'lead'=>$lead];$scoutPrompt="SCOUT REVENUE ENGINE LEAD DOSSIER\n\nLead UID: {$lead['lead_uid']}\nCRM Contact ID: {$crmId}\nName: {$lead['name']}\nEmail: {$lead['email']}\nPhone: {$lead['phone']}\nAddress: {$lead['address']}\nTown: {$lead['town']}\nType: {$lead['type']}\nTimeline: {$lead['timeline']}\nMessage: {$lead['message']}\nLead Score: {$lead['lead_score']}\n\nMISSION:\nComplete a real estate intelligence dossier before marking complete. Gather only legitimate/public/uploaded/licensed facts. Do not invent family, income, pets, social habits, phone numbers, emails, or property details.\n\nMinimum output:\n1. Verify/contact info status.\n2. Property and owner snapshot.\n3. Listing/expired history if available.\n4. Nearby recent sales / market context if available.\n5. Confidence score.\n6. Recommended call opening.\n7. Ready-for-Mark status or Needs-More-Research status.";$scoutCommission=g93_create_commission('scout','Revenue Lead Dossier: '.($lead['name']?:$lead['address']?:$lead['type']),$scoutPrompt,330,$meta);$scoutTask=g93_create_local_task('scout',$scoutCommission,'revenue_lead_dossier',$scoutPrompt,330,$meta);g93_timeline($lead['lead_uid'],$crmId,'Scout','scout_queued','Scout dossier queued','Scout must create a completed homeowner/lead dossier.',['commission_id'=>$scoutCommission,'task_id'=>$scoutTask]);$jessicaPrompt="JESSICA REVENUE ENGINE FOLLOW-UP\n\nLead UID: {$lead['lead_uid']}\nCRM Contact ID: {$crmId}\nName: {$lead['name']}\nEmail: {$lead['email']}\nPhone: {$lead['phone']}\nTown: {$lead['town']}\nType: {$lead['type']}\nMessage: {$lead['message']}\nLead Score: {$lead['lead_score']}\n\nMISSION:\nSend/prepare a human-touch acknowledgement and queue Mark callback. Do NOT call by voice. Do NOT trigger Retell. After Scout completes a dossier, prepare a targeted follow-up with the most relevant town/blog/market content. Use Mark's voice: warm, direct, human, not AI.";$jessicaCommission=g93_create_commission('jessica','Revenue Lead Follow-up: '.($lead['name']?:$lead['type']),$jessicaPrompt,320,$meta);$jessicaTask=g93_create_local_task('jessica',$jessicaCommission,'revenue_lead_followup',$jessicaPrompt,320,$meta);g93_timeline($lead['lead_uid'],$crmId,'Jessica','jessica_queued','Jessica follow-up queued','Jessica will acknowledge and prepare targeted follow-up.',['commission_id'=>$jessicaCommission,'task_id'=>$jessicaTask]);$callbackId=g93_create_callback($lead,$crmId);if(g93_table_exists('goliath_notifications')){g93_safe_insert('goliath_notifications',['notification_uid'=>g93_uid('note'),'executive_key'=>'goliath','title'=>'New revenue lead captured','message'=>($lead['name']?:'New lead').' — '.$lead['type'].' — score '.$lead['lead_score'],'url'=>'/dashboard/goliath-mission-control.php','status'=>'unread','priority'=>'high','metadata'=>g93_json($meta+['callback_id'=>$callbackId]),'created_at'=>gdb_now()]);}return ['scout_commission_id'=>$scoutCommission,'scout_task_id'=>$scoutTask,'jessica_commission_id'=>$jessicaCommission,'jessica_task_id'=>$jessicaTask,'callback_id'=>$callbackId];}}
